-- Baseline: schema equivalente ao que o Hibernate (ddl-auto=update) vinha criando.
-- Bancos que já existem recebem este baseline sem executá-lo (baseline-on-migrate).
create table categories (date timestamp(6) with time zone, id bigint generated by default as identity, owner bigint, name varchar(255), primary key (id), constraint UC_CATEGORY_NAME_OWNER unique (name, owner));
create table expense_category (category_id bigint not null, expense_id bigint not null);
create table expenses (value float(53) not null, date timestamp(6) with time zone, id bigint generated by default as identity, owner bigint, primary key (id));
create table users (id bigint generated by default as identity, email varchar(255) not null unique, name varchar(255), password varchar(255), username varchar(255) unique, primary key (id));
alter table if exists categories add constraint FKogxfku53ednee7sxtsvh50cfo foreign key (owner) references users;
alter table if exists expense_category add constraint FKqx2l30a6o8k856bb3hfdkc0q6 foreign key (category_id) references categories;
alter table if exists expense_category add constraint FKufbwutlod0q2j1tugcebnjrq foreign key (expense_id) references expenses;
alter table if exists expenses add constraint FKamhhvkghsrrbmirukikpulw57 foreign key (owner) references users;
